from bs4 import BeautifulSoup

def polish(html, lang):
    ar = lang == 'ar'
    def tr(en, arabic): return arabic if ar else en
    s = BeautifulSoup(html, 'html.parser')
    def frag(markup): return BeautifulSoup(markup, 'html.parser')
    def put(el, markup):
        el.clear()
        el.append(frag(markup))
    put(s.h1, tr('From ceiling to floor.<br><em>Make it feel like home.</em>', 'من السقف إلى الأرضية.<br><em>منزلك كما تتخيله.</em>'))
    s.select_one('.hero-intro').string = tr('Gypsum ceilings, painting, decoration and home renovation in Jubail and the Eastern Province. Bring your ideas. Start with a free site visit.', 'جبس بورد، دهانات، ديكور وترميم منازل في الجبيل والمنطقة الشرقية. اختر التفاصيل التي تحبها، ولنبدأ بمعاينة مجانية لمساحتك.')
    primary = tr('Arrange a free site visit', 'احجز معاينة مجانية')
    explore = tr('Explore the finishes', 'تصفح التشطيبات')
    put(s.select_one('.hero .actions'), f'<a class="button" href="#contact">{primary} ↗</a><a class="text-link" href="#services">{explore} ↓</a>')
    s.select_one('.hero-content').append(frag('<p class="hero-note">'+tr('Tell us about your space on WhatsApp. Arrange a visit with the team.', 'أخبرنا عن مساحتك عبر واتساب، وحدد موعد المعاينة مع الفريق.')+'</p>'))
    aside_title = tr('One space.<br>So many possibilities.', 'مساحة واحدة.<br>إمكانيات كثيرة.')
    aside_items = tr(['Sculpted ceilings & concealed light', 'Paint, texture & decorative details', 'Flooring & coordinated wall finishes'], ['أسقف جبسية وإضاءة مخفية', 'دهانات ولمسات ديكورية', 'أرضيات وتكسيات متناسقة'])
    s.select_one('.hero').append(frag(f'<aside class="hero-detail"><p class="eyebrow">{tr("THE DETAILS MAKE THE DIFFERENCE", "تفاصيل تصنع الفرق")}</p><h2>{aside_title}</h2><ul>'+''.join(f'<li>{x}</li>' for x in aside_items)+f'</ul><a href="#services">{explore} ↗</a></aside>'))
    proof = tr([('Free site visit','Start with your space'),('Jubail & Eastern Province','Local to your project'),('Apartments, villas & homes','Refresh, renovate or finish')], [('معاينة مجانية','لنبدأ بفهم مساحتك'),('الجبيل والمنطقة الشرقية','فريق قريب من مشروعك'),('شقق، فلل ومنازل','من التجديد إلى التشطيب')])
    ribbon=s.select_one('.ribbon');ribbon['class']=['proof-band']
    put(ribbon, ''.join(f'<div><span class="proof-icon" aria-hidden="true">{icon}</span><div><strong>{title}</strong><small>{detail}</small></div></div>' for (title,detail),icon in zip(proof,['✧','⌖','⌂'])))
    put(s.select_one('#services h2'),tr('Find your starting point.<br><em>We’ll help with the details.</em>','اختر البداية.<br><em>ودع التفاصيل علينا.</em>'))
    s.select_one('#services .section-heading>p').string=tr('Refreshing one room or finishing a whole home? Explore the services and choose what you need for your site visit.','هل ترغب في تجديد غرفة أم تشطيب منزلك بالكامل؟ استكشف الخدمات وحدد ما تحتاجه في طلب المعاينة.')
    for card,index in zip(s.select('.service'),[0,1,2,4]):
        a=card.select_one('a');a['href']='#contact';a['data-enquiry-service']=str(index)
        put(a,tr('Enquire about this service','اطلب معاينة لهذه الخدمة')+' <span aria-hidden="true">↗</span>')
    reno_title=tr('A familiar place.<br>A fresh perspective.','لا تحتاج إلى منزل جديد.<br>بل إلى رؤية جديدة.')
    reno_text=tr('Home renovation, apartment and villa finishing, and modern lighting coordination. Discuss the work, materials and finishes that suit your space during your site visit.','تجديد المنازل وتشطيب الشقق والفلل وتنسيق الإضاءة الحديثة. ناقش الأعمال المطلوبة والتشطيبات المناسبة لمساحتك مع الفريق خلال المعاينة.')
    reno_list=tr(['Room refreshes & residential renovation','Apartment & villa finishing','Coordinated paint, ceilings & lighting'],['تجديد الغرف والمساحات السكنية','تشطيبات الشقق والفلل','تنسيق الدهانات والأسقف والإضاءة'])
    s.select_one('.services').insert_after(frag(f'<div class="renovation-card"><div><p class="eyebrow">{tr("HOME RENOVATION & FINISHING","ترميم وتشطيب المنازل")}</p><h3>{reno_title}</h3></div><div><p>{reno_text}</p><ul>'+''.join(f'<li>{x}</li>' for x in reno_list)+f'</ul><a class="button" href="#contact" data-enquiry-service="3">{tr("Discuss your renovation","ناقش مشروع التجديد")} ↗</a></div></div>'))
    s.select_one('#work h2').string=tr('Get closer to the details.','اقترب من التفاصيل.')
    s.select_one('#work .section-heading>p').string=tr('Ceiling, wall and flooring imagery shared on the company website. Open any image to see the full detail.','أسقف وجدران وأرضيات من الصور المنشورة على موقع المؤسسة. اضغط على أي صورة لتراها كاملة.')
    names=tr(['Ceilings & lighting','Flooring & parquet','Walls & decoration'],['الجبس والإضاءة','الأرضيات والباركيه','الجدران والديكور'])
    view=tr('View full image','عرض الصورة كاملة')
    for i,fig in enumerate(s.select('.gallery figure')):
        button=s.new_tag('button',attrs={'type':'button','class':'gallery-open','data-gallery':str(i),'aria-label':view+': '+names[i]})
        fig.img.wrap(button);button.append(frag('<span class="gallery-zoom" aria-hidden="true">↗</span>'))
        put(fig.figcaption,f'<span>0{i+1}</span><strong>{names[i]}</strong>')
    steps=tr([('Share your idea','Send the type of work, your project location and photos of the space if available.'),('Arrange a site visit','Coordinate a free visit with the team to discuss what your space needs.'),('Discuss the details','Agree the scope, finishes, cost and timing before work begins.')],[('شاركنا فكرتك','أرسل نوع العمل وموقع المشروع وصور المساحة إن توفرت.'),('حدد موعد المعاينة','نسق معاينة مجانية مع الفريق لمناقشة احتياجات المكان.'),('ناقش الأعمال والتشطيبات','اتفق على التفاصيل والتكلفة والمدة قبل بدء العمل.')])
    s.select_one('#about').insert_after(frag(f'<section class="process-section"><div class="shell"><p class="eyebrow">{tr("FROM AN IDEA TO A FIRST STEP","من الفكرة إلى الخطوة الأولى")}</p><h2>{tr("Start with a simple conversation.","لنبدأ بمحادثة بسيطة.")}</h2><div class="process-grid">'+''.join(f'<article><span class="step-number">0{i+1}</span><h3>{title}</h3><p>{desc}</p></article>' for i,(title,desc) in enumerate(steps))+'</div></div></section>'))
    faqs=tr([('Is the site visit free?','Yes. The company advertises a free site visit. Contact the team to coordinate a time and confirm your project location.'),('Which areas do you serve?','The company is based in Jubail and serves the Eastern Province. Share your location to confirm a visit can be arranged.'),('Can I combine several services?','Yes. Services include gypsum ceilings, painting, interior decoration, flooring and home renovation. Include the work you need in your enquiry.'),('How do I get a price and timeline?','Cost and timing depend on the size and condition of the space, scope of work and chosen materials. Discuss these with the team during the site visit.'),('What should I share in my enquiry?','The service you need, city or neighbourhood, approximate room size, and any photos of the space or finishes you like.')],[('هل المعاينة مجانية؟','نعم، تعلن المؤسسة عن معاينة مجانية. تواصل مع الفريق لتنسيق الموعد وموقع المشروع.'),('ما المناطق التي تخدمونها؟','مقر المؤسسة في الجبيل، وتخدم مناطق المنطقة الشرقية. أرسل موقع مشروعك لتأكيد إمكانية المعاينة.'),('هل يمكن طلب أكثر من خدمة؟','نعم، تشمل الخدمات الجبس والأسقف والدهانات والديكور والأرضيات وترميم المنازل. اذكر الأعمال التي تحتاجها في طلبك.'),('كيف أعرف التكلفة والمدة؟','تختلف التكلفة والمدة بحسب مساحة المكان وحالته والأعمال والمواد المختارة. ناقش التفاصيل مع الفريق خلال المعاينة.'),('ما المعلومات المفيدة عند التواصل؟','نوع العمل، المدينة أو الحي، حجم المساحة التقريبي، وصور المكان أو أمثلة للتشطيبات التي تعجبك.')])
    s.select_one('#contact').insert_before(frag(f'<section id="faq" class="faq-section shell"><div><p class="eyebrow">{tr("GOOD TO KNOW","أسئلة شائعة")}</p><h2>{tr("Before we begin.","قبل أن نبدأ.")}</h2><a class="text-link dark-link" href="https://wa.me/966535056668">WhatsApp ↗</a></div><div class="faq-list">'+''.join(f'<details><summary>{q}<span aria-hidden="true">+</span></summary><p>{a}</p></details>' for q,a in faqs)+'</div></section>'))
    put(s.select_one('#contact h2'),tr('Your ideas deserve<br><em>a real starting point.</em>','أفكارك تستحق<br><em>بداية حقيقية.</em>'))
    s.select_one('#contact .contact-grid>div>p:not(.eyebrow)').string=tr('Choose your service and tell us about the space. WhatsApp will open with your message ready to send to the team.','اختر الخدمة وأخبرنا عن مساحتك. سيفتح واتساب برسالتك جاهزة للإرسال إلى الفريق.')
    s.select_one('form').insert(0,frag(f'<div class="form-heading"><h3>{tr("Request your free site visit","اطلب معاينتك المجانية")}</h3><p>{tr("The first step towards your refreshed space.","الخطوة الأولى نحو مساحتك الجديدة.")}</p></div>'))
    s.select_one('textarea')['placeholder']=tr('City, type of work, approximate room size…','المدينة، نوع العمل، مساحة الغرفة التقريبية…')
    s.select_one('header').insert_after(frag(f'<div class="preview-strip"><span>{tr("A preview by Glint Sites","معاينة من Glint Sites")}</span><button type="button" data-buy>{tr("Make this your website","اجعل هذا موقعك")} ↗</button></div>'))
    buy_title=tr('Show your work.<br>Make the next enquiry easier.','موقع يعرض أعمالك.<br>ويجعل التواصل أسهل.')
    buy_text=tr('This is a website concept for Adwaa Al Shuroq. Your photos, services and content can be refined before approval, then published on your business domain.','هذا تصور لموقع أضواء الشروق. يمكن تخصيص الصور والخدمات والمحتوى قبل الموافقة، ثم نشر الموقع على نطاق المؤسسة.')
    buy_list=tr(['Complete English & Arabic editions','Responsive design for phones & computers','Services, image gallery & WhatsApp enquiries'],['نسختان كاملتان بالعربية والإنجليزية','تصميم متجاوب للجوال والكمبيوتر','خدمات ومعرض صور وطلبات معاينة عبر واتساب'])
    s.body.append(frag(f'<dialog id="gallery-dialog" class="gallery-dialog" aria-label="{view}"><button type="button" class="dialog-close" data-close aria-label="{tr("Close image","إغلاق الصورة")}">×</button><img id="gallery-full" alt=""><p id="gallery-caption"></p></dialog><dialog id="buy-dialog" class="buy-dialog" aria-labelledby="buy-title"><button type="button" class="dialog-close" data-close aria-label="{tr("Close","إغلاق")}">×</button><p class="eyebrow">GLINT SITES × ADWAA AL SHUROQ</p><h2 id="buy-title">{buy_title}</h2><p>{buy_text}</p><ul>'+''.join(f'<li>{x}</li>' for x in buy_list)+f'</ul><p class="buy-note">{tr("No upfront payment. Review the website and request changes before approving.","دون دفع مقدم. راجع الموقع واطلب التعديلات قبل الموافقة.")}</p><a class="button" href="https://glintsites.com/#contact" target="_blank" rel="noopener">{tr("Talk to Nicolas","تحدث مع نيكولاس")} ↗</a><a class="text-link dark-link" href="https://glintsites.com/#plans" target="_blank" rel="noopener">{tr("Explore the plans","اطلع على الباقات")} ↗</a></dialog>'))
    s.body.append(frag(f'<div class="mobile-contact"><a href="tel:+966535056668">{tr("Call the team","اتصل بالفريق")}</a><a class="mobile-primary" href="#contact">{tr("Free site visit","معاينة مجانية")} ↗</a></div>'))
    return str(s)
